pub unsafe fn root_as_ss_anime_binary_unchecked(buf: &[u8]) -> SsAnimeBinary {
  unsafe { flatbuffers::root_unchecked::<SsAnimeBinary>(buf) }
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed SsAnimeBinary and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `SsAnimeBinary`.
pub unsafe fn size_prefixed_root_as_ss_anime_binary_unchecked(buf: &[u8]) -> SsAnimeBinary {
  unsafe { flatbuffers::size_prefixed_root_unchecked::<SsAnimeBinary>(buf) }
}
pub const SS_ANIME_BINARY_IDENTIFIER: &str = "SSAB";

#[inline]
pub fn ss_anime_binary_buffer_has_identifier(buf: &[u8]) -> bool {
  flatbuffers::buffer_has_identifier(buf, SS_ANIME_BINARY_IDENTIFIER, false)
}

#[inline]
pub fn ss_anime_binary_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  flatbuffers::buffer_has_identifier(buf, SS_ANIME_BINARY_IDENTIFIER, true)
}

#[inline]
pub fn finish_ss_anime_binary_buffer<'a, 'b, A: flatbuffers::Allocator + 'a>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
    root: flatbuffers::WIPOffset<SsAnimeBinary<'a>>) {
  fbb.finish(root, Some(SS_ANIME_BINARY_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_ss_anime_binary_buffer<'a, 'b, A: flatbuffers::Allocator + 'a>(fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>, root: flatbuffers::WIPOffset<SsAnimeBinary<'a>>) {
  fbb.finish_size_prefixed(root, Some(SS_ANIME_BINARY_IDENTIFIER));
}
